"use client";

import React, { useState } from "react";
import { Calendar, MapPin, Filter, ChevronDown } from "lucide-react";

/* --- 1. DATASET --- */
const holidaysData = [
  // --- 2025 ---
  { id: 1, name: "New Year's Day", date: "Jan 01", day: "Wednesday", year: "2025", type: "Public", region: "All" },
  { id: 2, name: "Republic Day", date: "Jan 26", day: "Sunday", year: "2025", type: "Public", region: "India" },
  { id: 3, name: "Ugadi", date: "Mar 30", day: "Sunday", year: "2025", type: "Optional", region: "Telangana" },
  { id: 4, name: "Good Friday", date: "Apr 18", day: "Friday", year: "2025", type: "Public", region: "Global" },
  { id: 5, name: "Independence Day", date: "Aug 15", day: "Friday", year: "2025", type: "Public", region: "India" },
  { id: 6, name: "Diwali", date: "Oct 20", day: "Monday", year: "2025", type: "Public", region: "India" },
  
  // --- 2026 ---
  { id: 7, name: "New Year's Day", date: "Jan 01", day: "Thursday", year: "2026", type: "Public", region: "All" },
  { id: 8, name: "Republic Day", date: "Jan 26", day: "Monday", year: "2026", type: "Public", region: "India" },
  { id: 9, name: "Holi", date: "Mar 03", day: "Tuesday", year: "2026", type: "Optional", region: "North India" },
  { id: 10, name: "Ugadi", date: "Mar 19", day: "Thursday", year: "2026", type: "Optional", region: "Telangana" },
  { id: 11, name: "Kannada Rajyotsava", date: "Nov 01", day: "Sunday", year: "2026", type: "Optional", region: "Karnataka" },
  { id: 12, name: "Christmas", date: "Dec 25", day: "Friday", year: "2026", type: "Public", region: "Global" },
];

export default function HolidayList() {
  const [selectedYear, setSelectedYear] = useState("2026");
  const [selectedRegion, setSelectedRegion] = useState("All");

  // Filter Logic: Matches Year AND (Matches Region OR Region is 'All' OR Holiday is Global/All)
  const filteredHolidays = holidaysData.filter((h) => {
    const yearMatch = h.year === selectedYear;
    const regionMatch = 
      selectedRegion === "All" || 
      h.region === selectedRegion || 
      h.region === "India" || 
      h.region === "Global" ||
      h.region === "All";
    return yearMatch && regionMatch;
  });

  return (
    <div className="min-h-screen bg-[#F8F9FB] dark:bg-[#050505] p-6 lg:p-12 font-sans">
      <div className="mx-auto max-w-3xl">
        
        {/* --- HEADER & FILTERS --- */}
        <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-6 mb-8">
          <div>
            <h1 className="text-3xl font-black tracking-tight text-gray-900 dark:text-white uppercase italic">
              Holiday List
            </h1>
            <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mt-1">
              Official Schedule
            </p>
          </div>

          <div className="flex gap-3">
            {/* Year Selector */}
            <div className="relative">
              <select 
                value={selectedYear}
                onChange={(e) => setSelectedYear(e.target.value)}
                className="appearance-none bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-2.5 pr-10 text-xs font-black uppercase tracking-widest text-gray-700 dark:text-white focus:ring-2 focus:ring-brand-500 outline-none cursor-pointer"
              >
                <option value="2025">2025</option>
                <option value="2026">2026</option>
              </select>
              <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
            </div>

            {/* Region Selector */}
            <div className="relative">
              <select 
                value={selectedRegion}
                onChange={(e) => setSelectedRegion(e.target.value)}
                className="appearance-none bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl px-4 py-2.5 pr-10 text-xs font-black uppercase tracking-widest text-gray-700 dark:text-white focus:ring-2 focus:ring-brand-500 outline-none cursor-pointer"
              >
                <option value="All">All Locations</option>
                <option value="Telangana">Telangana</option>
                <option value="Karnataka">Karnataka</option>
                <option value="North India">North India</option>
              </select>
              <MapPin size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
            </div>
          </div>
        </div>

        {/* --- LIST VIEW --- */}
        <div className="space-y-3">
          {filteredHolidays.length > 0 ? (
            filteredHolidays.map((holiday) => (
              <div 
                key={holiday.id}
                className="group flex items-center p-5 bg-white dark:bg-gray-900 rounded-[1.25rem] border border-gray-100 dark:border-gray-800 hover:border-brand-500/30 transition-all hover:shadow-lg hover:shadow-brand-500/5"
              >
                {/* Date Badge */}
                <div className="flex-shrink-0 w-16 h-16 bg-gray-50 dark:bg-gray-800 rounded-2xl flex flex-col items-center justify-center border border-gray-100 dark:border-gray-700/50 group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-colors">
                  <span className="text-[9px] font-black uppercase text-gray-400">{holiday.date.split(' ')[0]}</span>
                  <span className="text-xl font-black text-gray-900 dark:text-white">{holiday.date.split(' ')[1]}</span>
                </div>

                {/* Holiday Info */}
                <div className="ml-6 flex-1">
                  <h3 className="text-sm font-black text-gray-900 dark:text-white tracking-tight uppercase">
                    {holiday.name}
                  </h3>
                  <div className="flex items-center gap-3 mt-1.5">
                    <Badge type={holiday.type} />
                    <span className="text-[10px] font-bold text-gray-400 uppercase flex items-center gap-1">
                      <MapPin size={10} /> {holiday.region}
                    </span>
                  </div>
                </div>

                {/* Day */}
                <div className="text-right pl-4 border-l border-gray-100 dark:border-gray-800">
                  <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{holiday.day}</p>
                </div>
              </div>
            ))
          ) : (
            <div className="text-center py-12">
              <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">No holidays found for this selection.</p>
            </div>
          )}
        </div>

      </div>
    </div>
  );
}

/* --- UI ATOMS --- */
const Badge = ({ type }: { type: string }) => {
  const isOptional = type === "Optional";
  return (
    <span className={`px-2.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-widest ${
      isOptional 
      ? "bg-amber-100 text-amber-600 dark:bg-amber-500/10 dark:text-amber-500" 
      : "bg-emerald-100 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-500"
    }`}>
      {type}
    </span>
  );
};